 WHERE topic_uz = $$O'g'lim taxtda$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'nodira');

UPDATE fact_cards SET detail_uz = $$Turmush o'rtog'im Umarxon ham shoir edi va «Amiriy» taxallusi bilan she'r yozardi.

Uning devoni saqlanib qolgan. Umarxon shoirlarga homiylik qilgan: saroyida adabiy davra shakllangan, u yerda shoirlar to'planib she'r o'qigan va musobaqalashgan. Hukmdorning o'zi shoir bo'lishi adabiyot uchun qulay muhit yaratgan. Bizning oilamiz shu tariqa Qo'qon adabiy muhitining markazi bo'lib qolgan.$$
 WHERE topic_uz = $$Shoir turmush o'rtog'im$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'nodira');

UPDATE fact_cards SET detail_uz = $$She'rlarimni ikki tilda — o'zbek va fors-tojik tillarida yozganman.

O'sha davrda o'qimishli kishi ikki tilni ham bilishi odatiy hol edi: fors tili mumtoz she'riyat tili, turkiy til esa ona tili sanalardi. Ikki tilda yozish shoirdan har ikkala an'anani puxta bilishni talab qilardi. Mening forsiy she'rlarim mumtoz uslubga yaqin, o'zbekcha she'rlarim esa soddaroq va samimiyroq.$$
 WHERE topic_uz = $$Ijod tillarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'nodira');

UPDATE fact_cards SET detail_uz = $$She'rlarimda sevgi, sadoqat va vafo mavzulari asosiy o'rin tutadi.

