UPDATE fact_cards SET detail_uz = $$Bizning davrimizda Qo'qon saroyiga ko'plab shoir va olim to'plangan.

Umarxon davrida saroyda adabiy davra shakllangan bo'lib, unda shoirlar she'r o'qir, bahslashar va bir-birining mahoratini oshirardi. Shu davrada tuzilgan «Majmuayi shoiron» to'plamiga ko'plab shoirning she'rlari kiritilgan. Qo'qon shu tariqa XIX asr boshida Movarounnahrning adabiy markazlaridan biriga aylangan.$$
 WHERE topic_uz = $$Qo'qon adabiy muhiti$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'nodira');

UPDATE fact_cards SET detail_uz = $$Men xattotlarga qo'lyozma kitoblarni ko'chirtirib, ularni chiroyli bezattirganman.

O'sha davrda kitob qo'lda ko'chirilardi va bu uzoq mehnat talab qilardi: xattot matnni yozar, naqqosh sahifalarni bezar, muqovasoz esa muqova tayyorlardi. Bitta kitob ustidagi ish oylab davom etishi mumkin edi. Bunday kitoblar qimmat turgan va ularni asosan saroy hamda badavlat kishilar buyurtma qilgan. Homiylik tufayli ko'plab asar nusxasi ko'paygan va saqlanib qolgan.$$
 WHERE topic_uz = $$Kitobat san'atiga homiyligim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'nodira');

UPDATE fact_cards SET detail_uz = $$Bugun O'zbekistonda ko'chalar va maktablarga nomim berilgan.

