 WHERE topic_uz = $$Xotiram$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'nodira');

-- ================================= UVAYSIY =================================

UPDATE fact_cards SET detail_uz = $$1779-yilda Marg'ilonda tug'ilganman; asl ismim — Jahon.

Marg'ilon qadimdan hunarmandchilik shahri — u ipak to'qish va atlas bilan mashhur. Oilamiz ziyoli oila bo'lgan: otam she'riyat shaydosi, onam esa otin — ya'ni qizlarga saboq beradigan o'qituvchi edi. Shu muhitda men yoshligimdan savod chiqarganman va she'riyatga qiziqqanman.$$
 WHERE topic_uz = $$Tug'ilishim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'uvaysiy');

UPDATE fact_cards SET detail_uz = $$She'riyat ilmini akam Oxunjon hofizdan o'rganganman.

Hofiz — Qur'onni yod biladigan yoki mohir kuychi kishi. Akam she'riyatni yaxshi bilgan va menga aruz vazni, qofiya hamda badiiy tasvir qoidalarini o'rgatgan. O'sha davrda qizlar uchun rasmiy ta'lim muassasasi kam edi, shuning uchun bilim ko'pincha oila ichida uzatilardi. Mening taqdirimda oilaning roli hal qiluvchi bo'lgan.$$
 WHERE topic_uz = $$Ustozim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'uvaysiy');

UPDATE fact_cards SET detail_uz = $$Oilada savod chiqarib, avval xalfa, so'ng onam yonida maktabdorlik qilganman.

«Otin» yoki «otin oyi» — qizlarga saboq beradigan ayol o'qituvchi; «xalfa» esa uning yordamchisi. Bunday maktablar odatda uyda tashkil etilardi va u yerda qizlar savod chiqarar, she'r va axloq o'rganardi. Bu o'sha davrda qizlar uchun ta'lim olishning asosiy yo'li edi. Men keyinchalik bu ishni davom ettirib, saroyda ham dars berganman.$$
 WHERE topic_uz = $$Maktabdorligim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'uvaysiy');

UPDATE fact_cards SET detail_uz = $$Qo'qon saroyida Nodira va boshqa xotin-qizlarga she'riyatdan dars berganman.

Nodira meni maxsus taklif qilgan va men saroydagi ayollar adabiy davrasining ustozi bo'lganman. Darslarda aruz vazni, qofiya, badiiy san'atlar va mumtoz shoirlar ijodi o'rganilgan. Bunday davra o'sha davr uchun noyob edi: u ayollarga ijod bilan jiddiy shug'ullanish imkonini bergan. Shogirdlarim orasidan iqtidorli shoiralar yetishib chiqqan.$$
 WHERE topic_uz = $$Saroyda ustozligim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'uvaysiy');

UPDATE fact_cards SET detail_uz = $$Chiston — she'riy topishmoq: unda biror narsa nomi aytilmay, faqat belgilari tasvirlanadi va o'quvchi javobni topishi kerak.

Bu janr aql-zakovatni sinaydi va o'quvchini o'ylashga majbur qiladi. Chiston yozish mahorat talab qiladi: tasvir shu qadar aniq bo'lishi kerakki, javob topilsin, ammo shu qadar yashirin bo'lsinki, darrov bilinmasin. Mening chistonlarim shu janrning o'zbek adabiyotidagi eng yaxshi namunalari sanaladi va ular bugun ham bolalarga qiziqarli.$$
 WHERE topic_uz = $$Chistonlarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'uvaysiy');

UPDATE fact_cards SET detail_uz = $$Ijodim hajmi katta: yuzlab g'azal, muxammas, musaddas va uchta doston yozganman.

Bu raqamlar shuni ko'rsatadiki, men ijod bilan jiddiy va muntazam shug'ullanganman — ya'ni she'r yozish men uchun bo'sh vaqt mashg'uloti emas, kasb edi. G'azal — mumtoz she'riyatning asosiy janri, muxammas beshlik va musaddas oltilik bandlardan iborat. Har janrning o'z qoidasi bor va ularni bilish uzoq mashq talab qiladi.$$
 WHERE topic_uz = $$Ijodim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'uvaysiy');

UPDATE fact_cards SET detail_uz = $$«Shahzoda Hasan» va «Shahzoda Husan» dostonlarini hamda tarixiy mavzudagi dostonni yozganman.

