 WHERE topic_uz = $$Dostonlarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'uvaysiy');

UPDATE fact_cards SET detail_uz = $$Shoira Dilshod otin ma'lumotiga ko'ra, men Konibodom, Xo'jand va boshqa shaharlarda bo'lganman.

