 WHERE topic_uz = $$Safarlarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'uvaysiy');

UPDATE fact_cards SET detail_uz = $$1842-yilda Qo'qon egallangach, Marg'ilonga qaytib, umrimning oxirigacha shu yerda yashaganman.

