 WHERE topic_uz = $$Taxallusim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'uvaysiy');

UPDATE fact_cards SET detail_uz = $$Otam Siddiq she'riyat shaydosi edi, onam Chinnibibi esa otin bo'lib, qizlarga saboq berardi.

